import{_ as t,o as h,c as o,a3 as i}from"./chunks/framework.DX_KL3e0.js";const u=JSON.parse('{"title":"Chữ Ký Email","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/chu-ky-email.md","filePath":"chuc-nang/chu-ky-email.md","lastUpdated":1782143716000}'),a={name:"chuc-nang/chu-ky-email.md"};function g(r,n,c,d,l,e){return h(),o("div",null,[...n[0]||(n[0]=[i('<h1 id="chu-ky-email" tabindex="-1">Chữ Ký Email <a class="header-anchor" href="#chu-ky-email" aria-label="Permalink to &quot;Chữ Ký Email&quot;">​</a></h1><p>Module <strong>Chữ Ký Email</strong> giúp bạn tạo chữ ký email chuyên nghiệp theo chuẩn thương hiệu — tự động điền thông tin từ hồ sơ nhân sự, hỗ trợ logo, ảnh đại diện và liên kết mạng xã hội. Chữ ký hoạt động đúng trên Gmail, Outlook và mọi ứng dụng email phổ biến.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/email-signature</code> (menu <strong>Chữ Ký Email</strong> ở nhóm <em>Nhân Sự</em>).</li><li><strong>Ai dùng được:</strong> Tất cả người dùng đã đăng nhập (không cần quyền đặc biệt).</li><li><strong>Kết quả:</strong> File HTML email-safe — copy trực tiếp vào hộp thư hoặc tải về.</li></ul></div><h2 id="giao-dien-tong-quan" tabindex="-1">Giao diện tổng quan <a class="header-anchor" href="#giao-dien-tong-quan" aria-label="Permalink to &quot;Giao diện tổng quan&quot;">​</a></h2><p>Trang chia làm hai cột:</p><table tabindex="0"><thead><tr><th>Cột trái</th><th>Cột phải</th></tr></thead><tbody><tr><td>Chọn mẫu, nhập thông tin, chọn ảnh, cấu hình màu &amp; mạng xã hội</td><td>Xem trước trực tiếp (live preview) và các nút xuất</td></tr></tbody></table><p>Mọi thay đổi ở cột trái phản ánh ngay vào bản xem trước — không cần lưu để xem.</p><h2 id="buoc-1-—-chon-mau-chu-ky" tabindex="-1">Bước 1 — Chọn mẫu chữ ký <a class="header-anchor" href="#buoc-1-—-chon-mau-chu-ky" aria-label="Permalink to &quot;Bước 1 — Chọn mẫu chữ ký&quot;">​</a></h2><p>Hệ thống cung cấp <strong>6 mẫu</strong> thiết kế sẵn:</p><table tabindex="0"><thead><tr><th>Mẫu</th><th>Phong cách</th><th>Phù hợp</th></tr></thead><tbody><tr><td><strong>Sang Trọng</strong></td><td>Tên serif lớn, thanh gradient, avatar 96px, liên hệ ngang</td><td>Lãnh đạo, quản lý cấp cao</td></tr><tr><td><strong>Điều Hành</strong></td><td>Ảnh tròn, vạch màu dọc, icon liên hệ theo hàng</td><td>Quản lý, trưởng phòng</td></tr><tr><td><strong>Doanh Nghiệp</strong></td><td>Hai cột, logo bên phải, đường kẻ phân cách</td><td>Nhân viên văn phòng</td></tr><tr><td><strong>Một Dòng</strong></td><td>Gọn: tên · chức danh, liên hệ trên một hàng</td><td>Email ngắn, reply nhanh</td></tr><tr><td><strong>Thẻ Nhấn</strong></td><td>Thẻ bo góc, chân màu nền chứa liên hệ</td><td>Kinh doanh, bán hàng</td></tr><tr><td><strong>Tinh Gọn</strong></td><td>Thuần chữ, một đường kẻ nhấn</td><td>Môi trường thận trọng, formal</td></tr></tbody></table><p>Bấm vào mẫu để xem ngay ở cột phải — chọn mẫu không làm mất thông tin đã điền.</p><h2 id="buoc-2-—-đien-thong-tin" tabindex="-1">Bước 2 — Điền thông tin <a class="header-anchor" href="#buoc-2-—-đien-thong-tin" aria-label="Permalink to &quot;Bước 2 — Điền thông tin&quot;">​</a></h2><p>Nhấn <strong>✨ Điền từ hồ sơ</strong> để tự động lấy tên, chức danh, phòng ban, công ty, số điện thoại và email từ hồ sơ nhân sự của bạn trong hệ thống. Bạn vẫn có thể chỉnh tay từng trường sau khi điền tự động.</p><p><strong>Các trường thông tin:</strong></p><table tabindex="0"><thead><tr><th>Trường</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Họ và tên</td><td>Hiển thị nổi bật nhất trong chữ ký</td></tr><tr><td>Chức danh</td><td>Thường viết ngắn, ví dụ: <em>Trưởng phòng IT</em></td></tr><tr><td>Phòng ban</td><td>Tên phòng ban hiện tại</td></tr><tr><td>Công ty</td><td>Tên công ty hoặc tên thương hiệu</td></tr><tr><td>Điện thoại</td><td>Có thể gọi điện được khi bấm trên điện thoại</td></tr><tr><td>Email</td><td>Tạo liên kết <code>mailto:</code> tự động</td></tr><tr><td>Website</td><td>Tự động thêm <code>https://</code> nếu thiếu</td></tr><tr><td>Địa chỉ</td><td>Hiển thị với icon vị trí</td></tr><tr><td>Khẩu hiệu / Ghi chú</td><td>Ví dụ: <em>Vui lòng cân nhắc môi trường trước khi in email này</em></td></tr></tbody></table><h2 id="buoc-3-—-them-anh" tabindex="-1">Bước 3 — Thêm ảnh <a class="header-anchor" href="#buoc-3-—-them-anh" aria-label="Permalink to &quot;Bước 3 — Thêm ảnh&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Lưu ý quan trọng về ảnh trong email</p><p>Ảnh trong chữ ký email <strong>phải là URL công khai</strong> (https) — ứng dụng email của người nhận sẽ tải ảnh từ internet. Ảnh được upload vào hệ thống và lưu dưới địa chỉ công khai tự động.</p></div><p><strong>Ảnh đại diện:</strong></p><ul><li><strong>Tải lên</strong> — chọn ảnh từ máy tính (PNG/JPG, tối đa 2MB), hệ thống tự cắt vuông 240×240px.</li><li><strong>Ảnh của tôi</strong> — lấy ảnh đại diện bạn đã tải lên trong hồ sơ hệ thống.</li><li><strong>URL</strong> — dán đường dẫn ảnh công khai trực tiếp.</li></ul><p><strong>Logo công ty:</strong></p><ul><li><strong>Tải lên</strong> — logo của công ty bạn (PNG khuyến nghị để có nền trong suốt).</li><li><strong>Logo công ty</strong> — lấy logo đã đăng ký trong hệ thống (nếu công ty đã upload).</li><li><strong>URL</strong> — dán đường dẫn logo công khai.</li></ul><h2 id="buoc-4-—-mang-xa-hoi-mau-nhan" tabindex="-1">Bước 4 — Mạng xã hội &amp; màu nhấn <a class="header-anchor" href="#buoc-4-—-mang-xa-hoi-mau-nhan" aria-label="Permalink to &quot;Bước 4 — Mạng xã hội &amp; màu nhấn&quot;">​</a></h2><p><strong>Mạng xã hội:</strong> Dán đường dẫn đầy đủ của trang cá nhân/công ty vào ô tương ứng (LinkedIn, Facebook, X/Twitter, Instagram, YouTube, Zalo). Chỉ điền những kênh bạn muốn hiển thị — để trống kênh không dùng.</p><p><strong>Màu nhấn thương hiệu:</strong> Chọn từ 8 màu preset hoặc bấm ô vuông cuối để mở bảng màu tuỳ chỉnh. Màu nhấn được áp vào vạch phân cách, chức danh, icon liên hệ và logo mạng xã hội.</p><h2 id="buoc-5-—-luu-xuat" tabindex="-1">Bước 5 — Lưu &amp; Xuất <a class="header-anchor" href="#buoc-5-—-luu-xuat" aria-label="Permalink to &quot;Bước 5 — Lưu &amp; Xuất&quot;">​</a></h2><h3 id="luu-chu-ky" tabindex="-1">Lưu chữ ký <a class="header-anchor" href="#luu-chu-ky" aria-label="Permalink to &quot;Lưu chữ ký&quot;">​</a></h3><p>Bấm <strong>Lưu chữ ký</strong> (góc trên phải) để lưu vào tài khoản. Lần sau đăng nhập vào <code>/email-signature</code>, chữ ký được khôi phục tự động.</p><h3 id="xuat-đe-dung" tabindex="-1">Xuất để dùng <a class="header-anchor" href="#xuat-đe-dung" aria-label="Permalink to &quot;Xuất để dùng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nút</th><th>Tác dụng</th></tr></thead><tbody><tr><td><strong>Copy chữ ký</strong></td><td>Sao chép dạng rich-text (giữ nguyên định dạng, ảnh, màu) — dán thẳng vào Gmail/Outlook</td></tr><tr><td><strong>Copy mã HTML</strong></td><td>Sao chép mã HTML thô — dùng khi ứng dụng email yêu cầu dán HTML trực tiếp</td></tr><tr><td><strong>Tải HTML</strong></td><td>Tải file <code>.html</code> về máy để dùng offline hoặc chia sẻ</td></tr></tbody></table><h2 id="cai-đat-chu-ky-vao-hop-thu" tabindex="-1">Cài đặt chữ ký vào hộp thư <a class="header-anchor" href="#cai-đat-chu-ky-vao-hop-thu" aria-label="Permalink to &quot;Cài đặt chữ ký vào hộp thư&quot;">​</a></h2><h3 id="gmail" tabindex="-1">Gmail <a class="header-anchor" href="#gmail" aria-label="Permalink to &quot;Gmail&quot;">​</a></h3><ol><li>Mở <strong>Gmail</strong> → <strong>Cài đặt</strong> (biểu tượng ⚙️) → <strong>Xem tất cả cài đặt</strong>.</li><li>Tab <strong>Chung</strong> → cuộn xuống phần <strong>Chữ ký</strong> → bấm <strong>Tạo mới</strong>.</li><li>Đặt tên cho chữ ký, sau đó bấm vào vùng soạn thảo.</li><li>Nhấn <strong>Copy chữ ký</strong> trong AssetFlow → dán (<code>Ctrl+V</code>) vào hộp soạn thảo Gmail.</li><li>Chọn chữ ký mặc định ở phần <strong>Chữ ký mặc định</strong> → <strong>Lưu thay đổi</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Nếu ảnh không hiển thị sau khi dán, kiểm tra <code>NEXT_PUBLIC_APP_URL</code> đã được cấu hình đúng domain công khai của hệ thống.</p></div><h3 id="outlook-desktop" tabindex="-1">Outlook (Desktop) <a class="header-anchor" href="#outlook-desktop" aria-label="Permalink to &quot;Outlook (Desktop)&quot;">​</a></h3><ol><li>Mở <strong>Outlook</strong> → <strong>File</strong> → <strong>Tùy chọn</strong> → <strong>Thư</strong> → <strong>Chữ ký</strong>.</li><li>Bấm <strong>Mới</strong>, đặt tên.</li><li>Trong hộp soạn thảo, dán chữ ký đã copy.</li><li>Chọn chữ ký mặc định cho <strong>Tin nhắn mới</strong> và <strong>Trả lời/Chuyển tiếp</strong> → <strong>OK</strong>.</li></ol><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Ảnh không hiển thị trong email của người nhận?</strong> Nguyên nhân phổ biến: (1) Người nhận dùng ứng dụng email chặn ảnh từ xa theo mặc định — họ cần bấm &quot;Hiển thị ảnh&quot;. (2) URL ảnh không công khai (ảnh Google Drive dạng <code>/view?usp=sharing</code> không phải URL ảnh trực tiếp). Dùng nút <strong>Tải lên</strong> hoặc <strong>Ảnh của tôi</strong> thay vì dán URL Google Drive.</p><p><strong>Chữ ký bị mất định dạng khi dán vào Gmail?</strong> Dùng <strong>Copy chữ ký</strong> (không phải <strong>Copy mã HTML</strong>) — nút này sao chép dạng rich-text mà Gmail nhận dạng đúng. Đảm bảo dán bằng <code>Ctrl+V</code> (không phải <code>Ctrl+Shift+V</code> vì phím tắt đó bỏ định dạng).</p><p><strong>Có thể tạo nhiều mẫu chữ ký không?</strong> Phiên bản hiện tại lưu một chữ ký trên mỗi tài khoản. Bạn có thể đổi mẫu bất kỳ lúc nào và lưu lại. Tính năng nhiều mẫu sẽ có trong phiên bản tiếp theo.</p><p><strong>Font chữ hiển thị khác nhau trên máy người nhận?</strong> Chữ ký dùng hệ thống font tiêu chuẩn (Segoe UI trên Windows, San Francisco trên Mac, Roboto trên Android). Tên trong mẫu <strong>Sang Trọng</strong> dùng Georgia — font có sẵn ở mọi hệ điều hành. Không phụ thuộc Google Fonts nên không bị vỡ font khi email client chặn tài nguyên ngoài.</p>',40)])])}const m=t(a,[["render",g]]);export{u as __pageData,m as default};
